-- ========================================================
-- DATABASE SEED: WILAYAH INDONESIA (Provinsi & Kab/Kota)
-- Generated from emsifa/api-wilayah-indonesia v2
-- ========================================================

CREATE TABLE IF NOT EXISTS provinces (
  id VARCHAR(10) PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  capital VARCHAR(100),
  lat DECIMAL(10, 7),
  lng DECIMAL(10, 7),
  population BIGINT,
  total_area DECIMAL(12, 3)
);

CREATE TABLE IF NOT EXISTS regencies (
  id VARCHAR(10) PRIMARY KEY,
  province_id VARCHAR(10) REFERENCES provinces(id),
  name VARCHAR(100) NOT NULL,
  capital VARCHAR(100),
  lat DECIMAL(10, 7),
  lng DECIMAL(10, 7),
  population BIGINT,
  total_area DECIMAL(12, 3)
);


